const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jakartaPoint = ee.Geometry.Point([106.8, -6.2]);
  const roi = jakartaPoint.buffer(25000); // 25km buffer to capture urban sprawl
  const year1 = 1989;
  const year2 = 2004;

  // 2. Data Acquisition & Processing Function
  // Function to mask clouds, shadows, and water for Landsat 4/5/7 C2 L2
  function maskL457sr(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7)); // Cloud and Cloud Shadow
    const water = qa.bitwiseAnd(1 << 4);
    const mask = cloud.or(water).not(); // Keep pixels that are not cloud, shadow, or water
    return image.updateMask(mask);
  }

  // Function to calculate NDBI (Normalized Difference Built-up Index)
  // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
  // Landsat 5: SWIR1 is B5, NIR is B4
  function addNDBI(image) {
    const ndbi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
    return image.addBands(ndbi);
  }

  // Function to get a processed composite for a given year
  function getUrbanComposite(year) {
    const startDate = `${year}-01-01`;
    const endDate = `${year}-12-31`;

    let collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(startDate, endDate);

    // If Landsat 5 has no images, this is a fatal error for 1989.
    if (collection.size().getInfo() === 0) {
      return null;
    }

    const composite = collection
        .map(maskL457sr)
        .map(addNDBI)
        .median()
        .clip(roi);

    return composite;
  }

  // 3. Process data for both years
  const image1989 = getUrbanComposite(year1);
  const image2004 = getUrbanComposite(year2);

  if (!image1989 || !image2004) {
    console.log(`No images found for 1989 or 2004.`);
    console.log("B"); // Output B, as no change can be detected.
    return;
  }

  // Define a threshold for urban areas (NDBI > 0 is a common threshold)
  const urbanThreshold = 0;
  const urban1989 = image1989.select('NDBI').gt(urbanThreshold);
  const urban2004 = image2004.select('NDBI').gt(urbanThreshold);

  // 4. Calculation
  const scale = 1000;
  const areaReducer = ee.Reducer.sum();

  // Calculate the area of urban pixels. Multiply by pixel area.
  const urbanArea1989Result = urban1989.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: areaReducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  }).get('NDBI');

  const urbanArea2004Result = urban2004.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: areaReducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  }).get('NDBI');

  // Use evaluate to avoid blocking for getInfo() calls
  const [urbanArea1989, urbanArea2004] = await new Promise((resolve, reject) => {
    ee.List([urbanArea1989Result, urbanArea2004Result]).evaluate((result, error) => {
      if (error) reject(error);
      else resolve(result);
    });
  });

  // 5. Validation & Final Answer
  if (urbanArea1989 === null || urbanArea2004 === null) {
      console.log("Could not calculate urban area, likely due to no valid pixels after masking.");
      console.log("C2");
      return;
  }

  // Convert area from square meters to square kilometers
  const urbanKm1989 = urbanArea1989 / 1e6;
  const urbanKm2004 = urbanArea2004 / 1e6;

  console.log(`Urban extent in 1989: ${urbanKm1989.toFixed(2)} km^2`);
  console.log(`Urban extent in 2004: ${urbanKm2004.toFixed(2)} km^2`);

  if (urbanKm2004 > urbanKm1989) {
    console.log("Conclusion: Urban area increased.");
    console.log("A");
  } else {
    console.log("Conclusion: Urban area did not increase.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
